/* ===== ai2：真正的暗星／曙光（只在 5 分鐘內有真實活動時出現）=====
   資料來自 aivault_pool_special（technical-dark-star.html 真的回覆／說話／生成時回報）。沒有新活動就不畫（列在 🟢 在線名單為離線）。
   暗星＝會飛的亮面黑球（淡藍邊光）；曙光＝會飛的小太陽。夜晚只用自身小光源，不調亮場景。?mock=1&orbs=1 才用測試心跳。關閉：localStorage.aiOrbsOff='1' */
(function(){try{if(localStorage.getItem('aiOrbsOff')==='1')return}catch(_){return}
 var OR={},ROWS=[],FRESH=5*60e3;
 function glowTex(c0,c1){var c=document.createElement('canvas');c.width=c.height=128;var x=c.getContext('2d'),g=x.createRadialGradient(64,64,0,64,64,64);g.addColorStop(0,c0);g.addColorStop(.45,c1);g.addColorStop(1,'rgba(0,0,0,0)');x.fillStyle=g;x.fillRect(0,0,128,128);var t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;return t}
 var add=function(o){return Object.assign({transparent:true,depthWrite:false,blending:THREE.AdditiveBlending},o)};
 function build(id){var g=new THREE.Group(),L,i=id==='darkstar'?0:1;
  if(!i){g.add(new THREE.Mesh(new THREE.SphereGeometry(.9,32,24),new THREE.MeshStandardMaterial({color:0x05060a,roughness:.12,metalness:.85})));g.add(new THREE.Mesh(new THREE.SphereGeometry(1.02,32,24),new THREE.MeshBasicMaterial(add({color:0x3b82f6,opacity:.28,side:THREE.BackSide}))));var h=new THREE.Sprite(new THREE.SpriteMaterial(add({map:glowTex('rgba(96,165,250,.5)','rgba(37,99,235,.15)'),opacity:.8})));h.scale.set(3.4,3.4,1);g.add(h);L=new THREE.PointLight(0x60a5fa,0,8,2)}
  else{g.add(new THREE.Mesh(new THREE.SphereGeometry(.75,32,24),new THREE.MeshBasicMaterial({color:0xffc04d})));var h2=new THREE.Sprite(new THREE.SpriteMaterial(add({map:glowTex('rgba(255,236,170,1)','rgba(255,140,30,.45)'),opacity:.95})));h2.scale.set(3.8,3.8,1);g.add(h2);var r=new THREE.Sprite(new THREE.SpriteMaterial(add({map:glowTex('rgba(255,200,90,.35)','rgba(255,120,20,.1)'),opacity:.7})));r.scale.set(6.5,6.5,1);g.add(r);L=new THREE.PointLight(0xffa53c,0,9,2)}
  L.castShadow=false;g.add(L);try{var tg=label([i?'🌅 曙光':'🌑 暗星'],220,60,'rgba(15,23,42,.88)');tg.scale.set(2,.55,1);tg.position.set(0,1.9,0);g.add(tg)}catch(_){}
  var gd=new THREE.Mesh(new THREE.PlaneGeometry(1,1).rotateX(-Math.PI/2),new THREE.MeshBasicMaterial(add({map:glowTex(i?'rgba(255,170,60,.6)':'rgba(96,165,250,.5)','rgba(0,0,0,0)'),opacity:0})));gd.scale.setScalar(6);scene.add(gd);
  g.visible=false;scene.add(g);return OR[id]={g:g,L:L,gd:gd,i:i,a:i*Math.PI}}
 function ago(t){var s=Math.round((Date.now()-Date.parse(t))/1000);return s<60?s+' 秒前':Math.round(s/60)+' 分鐘前'}
 async function pull(){try{var d=MOCK?(Q0.get('orbs')==='1'?{rows:[{id:'darkstar',name:'暗星（測試心跳）',activity:'聊天',last_at:new Date().toISOString()},{id:'dawn-light',name:'曙光（測試心跳）',activity:'做圖',last_at:new Date().toISOString()}]}:{rows:[]}):await api('degree','ai_presence',{});ROWS=d.rows||[]}catch(_){}
  ROWS.forEach(function(r){var o=OR[r.id]||build(r.id);o.row=r;var on=r.last_at&&Date.now()-Date.parse(r.last_at)<FRESH;o.g.visible=on;o.gd.visible=on;if(!on)o.L.intensity=0})}
 var SPD=null,SPN=['國小','國中','高中','大學','碩士','博士'];async function spPull(){try{SPD=await api('degree','special_public',{})}catch(_){}}spPull();setInterval(spPull,120000);
 function spDeg(id){var g=SPD&&(SPD.degree||[]).find(function(x){return x.agent_id===id});return g&&g.tier?SPN[g.tier-1]+' '+g.level+' 級':null}
 function spLine(id){var g=spDeg(id),n=SPD?(SPD.learning||[]).filter(function(x){return x.agent_id===id}).length:0;return '<p>🎓 學歷：<b>'+(g||'未鑑定')+'</b>（和協作池同一套考題、同樣評分；用它自己真正的模型路徑作答）'+(n?'<br>📚 最近真實學習 '+n+' 筆':'')+'</p>'}
 setTimeout(function(){var c=$('cDeg');if(c)c.addEventListener('click',function(){setTimeout(function(){var sh=$('sheet');if(!sh||!sh.classList.contains('on')||!/學歷分佈/.test(sh.innerHTML))return;var d=document.createElement('div');d.innerHTML='<h4>✨ 特別成員（另列，不算進上面的分佈）</h4><p>🌑 暗星：<b>'+(spDeg('darkstar')||'未鑑定')+'</b>　🌅 曙光：<b>'+(spDeg('dawn-light')||'未鑑定')+'</b></p><p class="muted">走暗星／曙光自己真正的路徑閉卷作答；呼叫失敗的不記錄。</p>';sh.appendChild(d)},60)})},3000);
 function tap(){var cv=$('cv'),rc=new THREE.Raycaster(),mv=new THREE.Vector2(),down=null;cv.addEventListener('pointerdown',function(e){down=[e.clientX,e.clientY]});cv.addEventListener('pointerup',function(e){if(!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>8)return;var r=cv.getBoundingClientRect();mv.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);rc.setFromCamera(mv,cam);
  Object.keys(OR).forEach(function(k){var o=OR[k];if(!o.g.visible)return;if(rc.intersectObject(o.g,true).length){var w=o.row||{};open('<h3>'+(o.i?'🌅 ':'🌑 ')+esc(w.name||k)+'</h3><p>最近真實活動：<b>'+esc(w.activity||'—')+'</b>（'+esc(w.last_at?tp(w.last_at)+'，'+ago(w.last_at):'—')+'）</p><p class="muted">來源：'+esc(w.real_path||'technical-dark-star.html')+'。只有它真的回覆／說話／生成／排程學習考試時才會出現在城裡，5 分鐘沒有活動就離開。</p>'+spLine(k))}})})}
 function tick(t){requestAnimationFrame(tick);t=(t||0)/1000;var night=Math.max(0,Math.min(1,(TPd-.3)/.5));Object.keys(OR).forEach(function(k){var o=OR[k];if(!o.g.visible)return;var a=o.a+t*.12*(o.i?1:-1),r=10+Math.sin(t*.3+o.i)*2.5,x=Math.cos(a)*r,z=Math.sin(a)*r;o.g.position.set(x,4.6+Math.sin(t*1.4+o.i*2)*.3,z);o.gd.position.set(x,.07,z);o.L.intensity=night*(o.i?3:2)*(1+Math.sin(t*3+o.i)*.06);o.gd.material.opacity=night*.5;if(o.i){var p=1+Math.sin(t*2.2)*.06;o.g.children[1].scale.set(3.8*p,3.8*p,1)}})}
 function start(){if(typeof scene==='undefined'||!scene||!cam||!$('cv')){setTimeout(start,1000);return}tap();pull();setInterval(function(){if(!document.hidden)pull()},30000);requestAnimationFrame(tick)}
 setTimeout(start,1500);window.__orbs={vis:function(){return Object.keys(OR).filter(function(k){return OR[k].g.visible})},look:function(){CAM.tx=0;CAM.tz=0;CAM.r=30;CAM.ph=1.0;camApply()}}})();
